create or replace function public.iberfit_create_client_draft(p_payload jsonb) returns jsonb language plpgsql security definer set search_path = '' as $$ declare actor_id uuid := auth.uid(); actor_role public.iberfit_role; environment_name text; allowed boolean; blocked boolean; v_client_id uuid := gen_random_uuid(); v_profile_id uuid := gen_random_uuid(); normalized_email text := lower(trim(coalesce(p_payload->>'email',''))); client_name text := trim(coalesce(p_payload->>'name','')); modality public.client_modality; objective_text text := trim(coalesce(p_payload->>'objective','')); frequency_text text := trim(coalesce(p_payload->>'frequency','')); modules jsonb; begin if actor_id is null then raise exception 'Sesión no válida'; end if; select role into actor_role from public.user_profiles where user_id = actor_id; if actor_role is null or actor_role not in ('admin'::public.iberfit_role,'coach'::public.iberfit_role) then raise exception 'Solo Administración o Coach puede crear clientes'; end if; select value #>> '{}' into environment_name from public.iberfit_system_settings where key='environment'; select coalesce((value #>> '{}')::boolean,false) into allowed from public.iberfit_system_settings where key='real_data_allowed'; select coalesce((value #>> '{}')::boolean,true) into blocked from public.iberfit_system_settings where key='production_blocked'; if environment_name <> 'PRODUCTION' or not allowed or blocked then raise exception 'El entorno productivo no está autorizado para el alta'; end if; if length(client_name) < 2 then raise exception 'Ingresa el nombre del cliente'; end if; if normalized_email = '' or position('@' in normalized_email) <= 1 then raise exception 'Ingresa un correo válido'; end if; if objective_text = '' then raise exception 'Ingresa el objetivo principal'; end if; if frequency_text = '' then raise exception 'Ingresa la frecuencia prevista'; end if; begin modality := (p_payload->>'modality')::public.client_modality; exception when others then raise exception 'Modalidad no válida'; end; if exists (select 1 from public.client_intake_profiles where lower(email)=normalized_email) then raise exception 'Ya existe un expediente con ese correo'; end if; modules := case modality when 'Presencial'::public.client_modality then '["Inicio","Sesiones","Progreso","Informes"]'::jsonb else '["Inicio","Sesiones","Guiada en app","Progreso","Informes"]'::jsonb end; insert into public.clients(id,name,modality,objective,revision) values (v_client_id,client_name,modality,objective_text,0); insert into public.client_intake_profiles(client_id,email,address,zone,level,phase,frequency,restrictions,pain,history,equipment,preferences,primary_limiter,current_recommendation,pending,onboarding_status,created_by,updated_by) values (v_client_id,normalized_email,nullif(trim(p_payload->>'address'),''),nullif(trim(p_payload->>'zone'),''),nullif(trim(p_payload->>'level'),''),nullif(trim(p_payload->>'phase'),''),frequency_text,nullif(trim(p_payload->>'restrictions'),''),nullif(trim(p_payload->>'pain'),''),nullif(trim(p_payload->>'history'),''),nullif(trim(p_payload->>'equipment'),''),nullif(trim(p_payload->>'preferences'),''),nullif(trim(p_payload->>'primaryLimiter'),''),nullif(trim(p_payload->>'currentRecommendation'),''),nullif(trim(p_payload->>'pending'),''),'expediente',actor_id,actor_id); insert into public.client_app_profiles(id,client_id,modality,modules,version,revision,status,created_by) values (v_profile_id,v_client_id,modality,modules,1,0,'borrador',actor_id); if actor_role = 'coach'::public.iberfit_role then insert into public.client_assignments(client_id,coach_user_id,active) values (v_client_id,actor_id,true) on conflict (client_id,coach_user_id) do update set active=true; end if; insert into public.client_timeline_events(client_id,event_type,title,summary,visibility,source_table,source_id,status,priority,payload) values (v_client_id,'CLIENTE_CREADO','Expediente IBERFIT creado','Alta inicial preparada. El acceso del cliente todavía no ha sido enviado.','coach','clients',v_client_id,'registrado','normal',jsonb_build_object('modality',modality,'onboardingStatus','expediente','createdBy',actor_id)); insert into public.audit_events(event_type,entity_type,entity_id,actor_user_id,payload) values ('CLIENTE_CREADO','client',v_client_id::text,actor_id,jsonb_build_object('email',normalized_email,'modality',modality,'accessInvited',false)); return jsonb_build_object('client',(select to_jsonb(c) from public.clients c where c.id=v_client_id),'intake',(select to_jsonb(i) from public.client_intake_profiles i where i.client_id=v_client_id),'clientProfile',(select to_jsonb(p) from public.client_app_profiles p where p.id=v_profile_id),'accessInvited',false); end $$; revoke all on function public.iberfit_create_client_draft(jsonb) from public, anon; grant execute on function public.iberfit_create_client_draft(jsonb) to authenticated;;
